#include <iostream>
#include <new>
struct Sensor {
    int id;
    Sensor(int i) : id(i * 10) {}
};
int main() {
    alignas(Sensor) unsigned char buf[sizeof(Sensor)];
    Sensor* s = new (buf) Sensor(4);
    std::cout << s->id << "\n";
    s->~Sensor();
    return 0;
}

#include <iostream>
#include <span>
#include <array>
int main() {
    std::array<int, 5> a = {10, 20, 30, 40, 50};
    std::span<int> sub = std::span(a).subspan(1, 3);
    sub[1] += 5;
    std::cout << a[2] << " " << sub.size() << "\n";
    return 0;
}

#include <iostream>
#include <optional>
std::optional<int> parse_port(int p) {
    if (p <= 0 || p > 65535) return std::nullopt;
    return p;
}
int main() {
    auto a = parse_port(70000);
    auto b = parse_port(8080);
    std::cout << a.value_or(80) << " " << b.value_or(80) << "\n";
    return 0;
}
